SELECT 
FROM fm_task_parallel_add_sign
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND PARENT_TASK_ID = #{parentTaskId,jdbcType=VARCHAR}
ORDER BY BATCH_NO DESC
