UPDATE fm_task_parallel_add_sign
SET COMPLETED_COUNT = COMPLETED_COUNT + 1,
    AGREE_COUNT = AGREE_COUNT + CASE WHEN #{agreed,jdbcType=BOOLEAN} THEN 1 ELSE 0 END,
    DISAGREE_COUNT = DISAGREE_COUNT + CASE WHEN #{agreed,jdbcType=BOOLEAN} THEN 0 ELSE 1 END,
    LOCK_VERSION = LOCK_VERSION + 1,
    UDATE = #{updatedDate,jdbcType=TIMESTAMP}
WHERE OID = #{oid,jdbcType=CHAR}
  AND TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND STATUS = 'WAITING'
  AND LOCK_VERSION = #{lockVersion,jdbcType=INTEGER}
  AND COMPLETED_COUNT < TOTAL_COUNT

UPDATE fm_task_parallel_add_sign
SET STATUS = 'COMPLETED', COMPLETED_DATE = #{completedDate,jdbcType=TIMESTAMP},
    LOCK_VERSION = LOCK_VERSION + 1, UDATE = #{completedDate,jdbcType=TIMESTAMP}
WHERE OID = #{oid,jdbcType=CHAR} AND TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND STATUS = 'WAITING' AND LOCK_VERSION = #{lockVersion,jdbcType=INTEGER}
  AND COMPLETED_COUNT = TOTAL_COUNT

UPDATE fm_task_parallel_add_sign
SET STATUS = 'CANCELLED', CANCELLED_DATE = #{cancelledDate,jdbcType=TIMESTAMP},
    LOCK_VERSION = LOCK_VERSION + 1, UDATE = #{cancelledDate,jdbcType=TIMESTAMP}
WHERE OID = #{oid,jdbcType=CHAR} AND TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND STATUS = 'WAITING' AND LOCK_VERSION = #{lockVersion,jdbcType=INTEGER}
  AND COMPLETED_COUNT = 0
